contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public payable {
        require(newOwner != caller, "trivial");
        address ownerBefore = c.owner();
        bool callerIsOwner = (caller == ownerBefore);
        bool validArgs = (newOwner != address(0));

        bool reverted;
        try c.changeOwner(newOwner) { reverted = false; } catch { reverted = true; }

        address ownerAfter = c.owner();
        bool shouldSucceed = callerIsOwner && validArgs;

        assert(reverted != shouldSucceed);
        assert(shouldSucceed ? ownerAfter == newOwner : ownerAfter == ownerBefore);
    }
    receive() external payable {}
}

