    }

    function run(address spender, uint256 amount) public payable {
        require(spender != address(0), "spender zero");
        bool approveOk;
        try c.approve(spender, amount) returns (bool ok) {
            approveOk = ok;
        } catch {
            approveOk = false;
        }
        if (approveOk) {
            uint256 seen = c.allowance(address(this), spender);
            assert(seen == amount);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 amount) public payable {
        require(spender != address(0), "spender zero");

        // Drive the public entry point: state-changing call as its own top-level statement.
        // approve reverts only for zero spender, which the precondition excludes.
        c.approve(spender, amount);

        // Read the public view entry allowance as its own top-level statement.
        uint256 seen = c.allowance(address(this), spender);

        assert(seen == amount);
    }

    receive() external payable {}
}

