contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        address beforeOwner = c.owner();
        bool callerIsOwner = (caller == beforeOwner);

        // Impersonate `caller` by having this test contract call c.
        // Because msg.sender is this contract, we simulate the condition by requiring
        // that the caller matches this contract for the success branch.
        // The pure rule is checked unconditionally using observations from the public surface.

        // If caller is the current owner, we can directly drive the success path
        // because msg.sender == address(this) and we need caller == address(this)
        // to represent that situation. To keep the rule general and executable
        // the test focuses on the case caller == address(this).
        // However, a general property is asserted based on `callerIsOwner`.

        // Only attempt the state-changing call when the caller can actually be the owner.
        // For the non-owner branch we call changeOwner anyway, expecting a revert, but
        // msg.sender would then always be address(this); if caller != address(this)
        // that branch would incorrectly succeed when c.owner() == address(this).
        // So split the logic: if caller == address(this), perform the call and check the
        // poststate.  Otherwise, never perform the call and assert the trivial truth
        // that a non-owner cannot succeed?  But we need a single assert reached by some
        // execution.  We use a public view to verify owner() unchanged for the non-owner
        // path since we cannot impersonate.  This still gives a general rule:
        // after calling changeOwner as address(this), ownership is newOwner iff address(this)
        // was owner before, and unchanged otherwise (impossible here because msg.sender is
        // always address(this)).  To keep it general we check the effect of the actual call.

        // Drive through the public entry once, as this test contract.
        bool reverted;
        try c.changeOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: The call succeeds (reverted == false) exactly when the caller
        // (address(this)) is the owner before the call.  When it succeeds, owner() becomes
        // newOwner.  When it reverts, owner() is unchanged.
        bool callerWasOwner = (address(this) == beforeOwner);

        // The actual rule over the observed values:
        // (callerWasOwner && !reverted && afterOwner == newOwner) || (!callerWasOwner && reverted && afterOwner == beforeOwner)
        assert(
            (callerWasOwner && !reverted && afterOwner == newOwner) ||
            (!callerWasOwner && reverted && afterOwner == beforeOwner)
        );
    }

    receive() external payable {}
}

