contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0));
        require(sender != recipient);
        require(amount > 0);
        require(address(this).balance >= 0);

        // Fund the sender so a transfer can succeed, using the public mint/transfer
        // path if available: we cannot mint, so use the existing balance.
        // Approve this contract as spender from sender is not possible from here.
        // Instead, transferFrom is called with msg.sender = this test contract as spender,
        // and sender must have approved this contract beforehand. Since setup must be calls
        // on c at the top of run, do an approve from this contract and drive
        // transferFrom only when sender already has balance and allowance.

        // Read before-values through the public surface.
        uint256 beforeSenderBal = c.balanceOf(sender);
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeAllowance = c.allowance(sender, address(this));

        // The only call that changes state, made as its own top-level statement.
        bool callSucceeded;
        try c.transferFrom(sender, recipient, amount) returns (bool ok) {
            callSucceeded = ok;
        } catch {
            callSucceeded = false;
        }

        // The general rule: if transferFrom completed successfully, then the allowance
        // was reduced by exactly amount (or to zero if the deduction would underflow,
        // but the contract reverts in that case), and the recipient's balance increased
        // by exactly amount.
        assert(
            !callSucceeded
            || (
                c.allowance(sender, address(this)) + amount == beforeAllowance
                && c.balanceOf(recipient) == beforeRecipientBal + amount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount, uint256 approvalAmount) public payable {
        require(sender != address(0) && recipient != address(0));
        require(sender != recipient);
        require(amount > 0);

        // As the test contract is the spender, set its allowance from sender.
        // We cannot call approve from sender here; instead we call approve on c as msg.sender
        // which sets allowance[sender][this]? No, c.approve sets allowance[msg.sender][spender].
        // msg.sender here is the test contract, so we can only approve spender = address(this).
        // That is the sender? That would be sender == address(this) which is not allowed
        // (sender is a parameter). So we need to have the test contract itself be the sender.
        // Therefore fix: use the test contract as sender so it can set its own allowance.
        // We'll call c.approve(address(this), approvalAmount) -> allowance[address(this)][address(this)]
        // then call c.transferFrom(address(this), recipient, amount).

        // Before values (sender will be this test contract)
        address actualSender = address(this);
        uint256 beforeAllowance = c.allowance(actualSender, actualSender);
        uint256 beforeRecipientBal = c.balanceOf(recipient);

        // Set the allowance from actualSender (this contract) to actualSender (this contract) for transferFrom.
        c.approve(actualSender, approvalAmount);

        // The deciding call.
        bool callSucceeded;
        try c.transferFrom(actualSender, recipient, amount) returns (bool ok) {
            callSucceeded = ok;
        } catch {
            callSucceeded = false;
        }

        // General rule: if the transferFrom completed successfully, the allowance of the spender
        // (actualSender) decreased by exactly the transferred amount.
        uint256 finalAllowance = c.allowance(actualSender, actualSender);
        assert(
            !callSucceeded
            || (
                approvalAmount >= amount
                && finalAllowance == approvalAmount - amount
            )
        );
    }

    receive() external payable {}
}

